insert into public.policy_raw (kind, external_id, title, url, payload, retrieved_at, retrieved_by) values (
  '보조금24API', '654000000009', '전북청년 지역정착 지원사업', 'https://plus.gov.kr/portal/benefitV2/benefitTotalSrvcList/benefitSrvcDtl?svcSeq=2128390&bnefType=all&svcId=654000000009',
  '{"api":"행정안전부 대한민국 공공서비스(혜택) 정보 — https://api.odcloud.kr/api/gov24/v3","query":{"cond[서비스ID::EQ]":"654000000009"},"policyId":"jeonbuk-youth-settlement-support","fetchedAt":"2026-11-12T11:13:49.472Z","serviceList":{"currentCount":1,"data":[{"등록일시":"20241220100832","부서명":"인구청년정책과","사용자구분":"개인","상세조회URL":"https://plus.gov.kr/portal/benefitV2/benefitTotalSrvcList/benefitSrvcDtl?svcSeq=2128390&bnefType=all&svcId=654000000009","서비스ID":"654000000009","서비스명":"전북청년 지역정착 지원사업","서비스목적요약":"매월 30만원 × 최대 12개월","서비스분야":"생활안정","선정기준":null,"소관기관명":"전북특별자치도","소관기관유형":"광역시도","소관기관코드":"6540000","수정일시":"20260805181521","신청기한":"2026. 3. 6. (금)~ 3. 20.(금) 17:00/2026. 3.30.(월)~4.10.(금) 17:00","신청기한유형":"직접입력","신청방법":"기타 온라인신청","전화문의":"전북특별자치도 인구청년정책과/063-280-3884","접수기관":null,"조회수":4498,"지원내용":"매월 30만원 × 최대 12개월\r\n* 신용카드(체크카드 포함)와 연계한 포인트 및 지역화폐 지급","지원대상":"가. 연 령 : 2025.12.31.기준 18세 이상 ~ 39세 이하(1986.1.1.~2007.12.31.)\r\n\r\n나. 거주지역 및 거주기간           \r\n  ○ 공고일 기준 주민등록상 주소지가 전북특별자치도로 되어 있는 자\r\n  ○ 청년 연령기간(18세~39세) 동안 공고일 기준 도내에서 최소 1년 이상 거주       \r\n  ○ 주민등록상 전북특별자치도에 거주한 기간만을 거주기간으로 인정\r\n  ○ 도내에서의 거주지 이동이 있는 경우에는 거주기간 인정\r\n  ○ 도내에서 도외로 전출 후 다시 도내로 전입한 경우, 전입한 시점부터 인정    \r\n\r\n다. 종사분야 및 재직기간      \r\n   ○ (종사분야) 농업, 임업, 어업, 중소기업, 문화예술, 연구소기업  \r\n   ○ (재직기간) 공고일 기준 최근 3개월 이상 근무을 지속하고 있는 청년    \r\n\r\n라. 소득기준   \r\n  ○ 가구기준 중위소득 150% 이하인 자    \r\n ‣ 건강보험료 납부확인서, 건강보험 자격확인서를 통해 소득기준과 가구원수 확인\r\n ‣ 국민건강보험공단 홈페이지 (http://www.nhis.or.kr) 또는 팩스 신청 등 발급 \r\n  ○ 최근 3개월(‘25.10~12월) 평균 건강보험료 “고지 금액”이 가구기준 중위소득 150%의 건강보험료 고지 금액 이하여야 함  \r\n\r\n마. 졸업기준\r\n  ○ 최종학력은 마지막으로 입학한 학교를 최종학력으로 간주","지원유형":"기타"}],"matchCount":1,"page":1,"perPage":10,"totalCount":10942},"serviceDetail":{"currentCount":1,"data":[{"공무원확인구비서류":"해당없음","구비서류":"① 주민등록 초본(주소이력 포함)\r\n② 건강보험료 납부확인서\r\n③ 건강보험 자격확인서\r\n④ 4대보험 가입확인서\r\n⑤ 최종학력증명서 외","문의처":"전북특별자치도 인구청년정책과/063-280-3884","법령":null,"본인확인필요구비서류":"해당없음","서비스ID":"654000000009","서비스명":"전북청년 지역정착 지원사업","서비스목적":"청년의 경제적 자립과 안정적 지역정착 지원","선정기준":null,"소관기관명":"전북특별자치도","수정일시":"2026-08-05","신청기한":"2026. 3. 6. (금)~ 3. 20.(금) 17:00/2026. 3.30.(월)~4.10.(금) 17:00","신청기한유형":"직접입력","신청방법":"- 전북청년 지역정착 지원사업 사이트(ttd.ezwel.com)\r\n   ※ 직접방문, 우편 등을 통한 접수는 불가하며, 기타 자세한 사항은 사이트 참조","온라인신청사이트URL":"https://ttd.ezwel.com/","자치법규":"전북특별자치도 청년 기본 조례","접수기관명":null,"지원내용":"매월 30만원 × 최대 12개월\r\n* 신용카드(체크카드 포함)와 연계한 포인트 및 지역화폐 지급","지원대상":"가. 연 령 : 2025.12.31.기준 18세 이상 ~ 39세 이하(1986.1.1.~2007.12.31.)\r\n\r\n나. 거주지역 및 거주기간           \r\n  ○ 공고일 기준 주민등록상 주소지가 전북특별자치도로 되어 있는 자\r\n  ○ 청년 연령기간(18세~39세) 동안 공고일 기준 도내에서 최소 1년 이상 거주       \r\n  ○ 주민등록상 전북특별자치도에 거주한 기간만을 거주기간으로 인정\r\n  ○ 도내에서의 거주지 이동이 있는 경우에는 거주기간 인정\r\n  ○ 도내에서 도외로 전출 후 다시 도내로 전입한 경우, 전입한 시점부터 인정    \r\n\r\n다. 종사분야 및 재직기간      \r\n   ○ (종사분야) 농업, 임업, 어업, 중소기업, 문화예술, 연구소기업  \r\n   ○ (재직기간) 공고일 기준 최근 3개월 이상 근무을 지속하고 있는 청년    \r\n\r\n라. 소득기준   \r\n  ○ 가구기준 중위소득 150% 이하인 자    \r\n ‣ 건강보험료 납부확인서, 건강보험 자격확인서를 통해 소득기준과 가구원수 확인\r\n ‣ 국민건강보험공단 홈페이지 (http://www.nhis.or.kr) 또는 팩스 신청 등 발급 \r\n  ○ 최근 3개월(‘25.10~12월) 평균 건강보험료 “고지 금액”이 가구기준 중위소득 150%의 건강보험료 고지 금액 이하여야 함  \r\n\r\n마. 졸업기준\r\n  ○ 최종학력은 마지막으로 입학한 학교를 최종학력으로 간주","지원유형":"기타","행정규칙":null}],"matchCount":1,"page":1,"perPage":10,"totalCount":10942},"supportConditions":{"currentCount":1,"data":[{"JA0101":"Y","JA0102":"Y","JA0110":18,"JA0111":39,"JA0201":"Y","JA0202":"Y","JA0203":"Y","JA0204":"Y","JA0205":null,"JA0301":"Y","JA0302":"Y","JA0303":"Y","JA0313":"Y","JA0314":"Y","JA0315":"Y","JA0316":"Y","JA0317":null,"JA0318":null,"JA0319":null,"JA0320":"Y","JA0322":"Y","JA0326":"Y","JA0327":"Y","JA0328":"Y","JA0329":"Y","JA0330":"Y","JA0401":"Y","JA0402":"Y","JA0403":"Y","JA0404":"Y","JA0410":"Y","JA0411":"Y","JA0412":"Y","JA0413":"Y","JA0414":"Y","JA1101":null,"JA1102":null,"JA1103":null,"JA1201":null,"JA1202":null,"JA1299":null,"JA2101":null,"JA2102":null,"JA2103":null,"JA2201":null,"JA2202":null,"JA2203":null,"JA2299":null,"서비스ID":"654000000009","서비스명":"전북청년 지역정착 지원사업"}],"matchCount":1,"page":1,"perPage":10,"totalCount":10942}}'::jsonb,
  '2026-11-12T11:13:49.472Z', '노찬영 PC Claude (보조금24 API, raw/2026-11-12/)');
