insert into public.policy_raw (kind, external_id, title, url, payload, retrieved_at, retrieved_by) values (
  '온통청년API', '20250617005400110952', '미혼청년 주거급여 분리지급', 'https://www.youthcenter.go.kr/go/ythip/getPlcy?rtnType=json&plcyNo=20250617005400110952',
  '{"api":"온통청년 청년정책 API — https://www.youthcenter.go.kr/go/ythip/getPlcy","query":{"plcyNo":"20250617005400110952","rtnType":"json","pageNum":1,"pageSize":5},"policyId":"youth-housing-benefit-split-payment","fetchedAt":"2026-11-12T11:13:49.899Z","response":{"resultCode":200,"resultMessage":"성공적으로 데이터를 가지고 왔습니다.","result":{"youthPolicyList":[{"plcyNo":"20250617005400110952","bscPlanCycl":"1","bscPlanPlcyWayNo":"002","bscPlanFcsAsmtNo":"005","bscPlanAsmtNo":"010","pvsnInstGroupCd":"0054001","plcyPvsnMthdCd":"0042013","plcyAprvSttsCd":"0044002","plcyNm":"미혼청년 주거급여 분리지급","plcyKywdNm":null,"plcyExplnCn":"부모와 따로 거주하는 청년세대에게 주거급여를 별도 분리지급하여 안정적인 미래준비와 자립 도모","lclsfNm":null,"mclsfNm":null,"plcySprtCn":"주거급여 수급가구원 중 취학,구직 등의 사유로 부모와 따로 거주하는 20대 미혼자녀에게 별도 주거급여 지급\n(지원내용) 부모와 청년 각각의 거주지, 가구원수에 따라 산정한 기준임대료를 상한으로 실제 임차료를 지급하고, 자기부담분은 분리된 가구 각각의 가구원 수에 비례하여 적용","sprvsnInstCd":"1613000","sprvsnInstCdNm":"국토교통부","sprvsnInstPicNm":"","operInstCd":"       ","operInstCdNm":"","operInstPicNm":"","sprtSclLmtYn":"N","aplyPrdSeCd":"0057003","bizPrdSeCd":"0056002","bizPrdBgngYmd":"        ","bizPrdEndYmd":"        ","bizPrdEtcCn":"''21년~","plcyAplyMthdCn":"□ 읍면동 주민센터에 관련 상담 신청 → 신청서, 금융정보 등 제공 동의서, 임대차 계약서(해당자 한함) 등 기타 구비서류 안내받아 접수\n□ 복지로 서비스신청을 통한 온라인신청 : 복지로 로그인 > 서비스 신청 > 복지서비스 신청 > 복지급여 신청 > 저소득층 > ''주거급여'' 또는 ''청년주거급여분리지급''","srngMthdCn":"","aplyUrlAddr":"https://www.bokjiro.go.kr/ssis-tbu/twataa/wlfareInfo/moveTWAT52011M.do?wlfareInfoId=WLF00003201","sbmsnDcmntCn":"","etcMttrCn":"","refUrlAddr1":"","refUrlAddr2":"","sprtSclCnt":"0","sprtArvlSeqYn":"N","sprtTrgtMinAge":"19","sprtTrgtMaxAge":"29","sprtTrgtAgeLmtYn":"N","mrgSttsCd":"0055003","earnCndSeCd":"0043003","earnMinAmt":"0","earnMaxAmt":"0","earnEtcCn":"중위소득 48% 이하","addAplyQlfcCndCn":"주거급여 수급가구 내 부모와 떨어져 사는 청년에게 주거급여를 분리하여 지급\n- 임차급여 또는 수선유지급여를 지급받는 수급가구 내 만 19세 이상 30세 미만의 미혼자녀\n- 청년명의의 임대차계약을 체결하고 임차료를 지불하는 청년에게 지급(전입신고 필수)\n- 주거급여 수급가구의 부모와 청년이 주민등록상 시·군을 달리하는 경우 인정하되, 동일 시·군이라도 보장기관이 인정하는 경우는 예외로 함","ptcpPrpTrgtCn":"주거급여가 불필요하거나, 타 법령 등에 의하여 주거를 제공받고 있는 수급자에 대해서는 주거급여를 지급하지 않음","inqCnt":"8238","rgtrInstCd":"1613000","rgtrInstCdNm":"국토교통부","rgtrUpInstCd":"0000000","rgtrUpInstCdNm":"국토교통부","rgtrHghrkInstCd":"1613000","rgtrHghrkInstCdNm":"국토교통부","zipCd":"11110,11140,11170,11200,11215,11230,11260,11290,11305,11320,11350,11380,11410,11440,11470,11500,11530,11545,11560,11590,11620,11650,11680,11710,11740,12110,12130,12150,12170,12190,12210,12240,12270,12300,12330,12710,12720,12730,12740,12750,12760,12770,12780,12790,12800,12810,12820,12830,12840,12850,12860,12870,26110,26140,26170,26200,26230,26260,26290,26320,26350,26380,26410,26440,26470,26500,26530,26710,27110,27140,27170,27200,27230,27260,27290,27710,27720,28125,28177,28185,28200,28237,28245,28290,28710,28720,30110,30140,30170,30200,30230,31110,31140,31170,31200,31710,36110,43111,43112,43113,43114,43130,43150,43720,43730,43740,43745,43750,43760,43770,43800,44131,44133,44150,44180,44200,44210,44230,44250,44270,44710,44760,44770,44790,44800,44810,44825,47111,47113,47130,47150,47170,47190,47210,47230,47250,47280,47290,47730,47750,47760,47770,47820,47830,47840,47850,47900,47920,47930,47940,48121,48123,48125,48127,48129,48170,48220,48240,48250,48270,48310,48330,48720,48730,48740,48820,48840,48850,48860,48870,48880,48890,50110,50130,52111,52113,52130,52140,52180,52190,52210,52710,52720,52730,52740,52750,52770,52790,52800","plcyMajorCd":"0011009","jobCd":"0013010","schoolCd":"0049010","aplyYmd":"","frstRegDt":"2025-06-17 15:06:29","lastMdfcnDt":"2026-01-01 00:00:00","sbizCd":"0014010"}]}}}'::jsonb,
