insert into public.policy_raw (kind, external_id, title, url, payload, retrieved_at, retrieved_by) values (
  '온통청년API', '20260319005400112218', '(국토부) 26년 청년월세 지원사업', 'https://www.youthcenter.go.kr/go/ythip/getPlcy?rtnType=json&plcyNo=20260319005400112218',
  '{"api":"온통청년 청년정책 API — https://www.youthcenter.go.kr/go/ythip/getPlcy","query":{"plcyNo":"20260319005400112218","rtnType":"json","pageNum":1,"pageSize":5},"policyId":"moland-youth-rent-support","fetchedAt":"2026-11-12T11:13:48.833Z","response":{"resultCode":200,"resultMessage":"성공적으로 데이터를 가지고 왔습니다.","result":{"youthPolicyList":[{"plcyNo":"20260319005400112218","bscPlanCycl":"2","bscPlanPlcyWayNo":"003","bscPlanFcsAsmtNo":"009","bscPlanAsmtNo":"030","pvsnInstGroupCd":"0054001","plcyPvsnMthdCd":"0042006","plcyAprvSttsCd":"0044002","plcyNm":"(국토부) 26년 청년월세 지원사업","plcyKywdNm":null,"plcyExplnCn":"고금리·고물가 등으로 경제적 어려움을 겪는 청년층의 주거비 부담 경감을 위해 월 최대 20만원씩 최장 24개월간 월세를 지원합니다(생애 1회).","lclsfNm":null,"mclsfNm":null,"plcySprtCn":"월세로 거주하는 청년을 대상으로 실제 납부하는 임대료를 최대 480만원(월 최대 20만원)까지 최대 24개월(회) 동안 매월 분할하여 지원합니다.\n○ 실제 월세 범위 내에서 지원하며, 임차보증금, 관리비 등은 제외 후 지원합니다.\n○ 주거급여 수급자의 경우 주거급여액 중 월차임분(청년 주거급여 분리지급액 포함)을 차감한 금액만 지원합니다.\n○ 방학기간 등으로 수급기간이 연속적이지 않더라도 지급기간 내 24개월(회)분을 지원합니다.\n\n지급기간 : ~2028년 12월\n○ 2026년 신규 수혜자는 2028년 12월까지 지원\n○ 2026년에 선정된 이후 지급 중지 등으로 인해 ''28년까지 24개월(회) 지원을 다 못받았다면, ''29년 이후 정기 신청기간에 재신청(소득, 재산 재심사)하여 선정될 때 지원을 재개하고 잔여횟수만 지원","sprvsnInstCd":"1613000","sprvsnInstCdNm":"국토교통부","sprvsnInstPicNm":"","operInstCd":"       ","operInstCdNm":"","operInstPicNm":"","sprtSclLmtYn":"N","aplyPrdSeCd":"0057001","bizPrdSeCd":"0056001","bizPrdBgngYmd":"20260901","bizPrdEndYmd":"20281231","bizPrdEtcCn":"","plcyAplyMthdCn":"주소지 관할 주민센터에 청년 본인이 방문하거나 복지로(bokjiro.go.kr)에서 온라인으로 신청이 가능합니다.\n○ 방문 신청 시 청년 본인이 신청하는 것이 원칙이나, 불가피한 경우 대리인(①법정대리인 ②주민등록상 동일 세대원(동거인 제외) ③동일 세대원이 아닌 배우자 및 직계존·비속)도 신청이 가능하며, 해당 경우에도 월세는 청년 본인 계좌로 지급됩니다.\n※ 대리인 신청 시 위임장, 대리인 신분증(주민등록증, 운전면허증, 여권 등)을 지참 후 방문\n※ 단, 압류방지통장으로 입금은 불가하며, 본인 명의의 계좌 개설이 곤란한 경우 등은 기초생활보장제도 계좌관리 원칙에 따름\n\n복지로 온라인신청 경로는 다음과 같습니다.\n○ 복지로 로그인 > 서비스 신청 > 복지서비스 신청 > 복지급여 신청 > 기타 > 청년월세지원","srngMthdCn":"신청은 ''26년 3월 30일 09:00부터 ''26년 5월 29일 16:00까지 가능하며, 지자체에서 소득·재산 요건 검증을 거쳐 9월에 선정자 공지 및 월세 지원이 이뤄질 예정입니다.","aplyUrlAddr":"https://bokjiro.go.kr","sbmsnDcmntCn":"월세지원 신청서, 소득·재산 신고서, 임대차계약서 및 최근 3개월간 월세 이체 증빙서류, 통장 사본, 가족관계증명서 등","etcMttrCn":"청년가구 소득·재산평가액 산정 기준은 다음과 같습니다.\n\n○ 소득평가액이 「국민기초생활 보장법」 제2조제11호에 따른 기준 중위소득의 60% 이하\n- 소득평가액 = ①근로소득 + ②사업소득 + ③재산소득 + ④공적이전소득 - ⑤근로·사업소득공제\n\n○ 일반재산, 자동차 등의 재산에 관하여 총재산가액이 1.22억원 이하\n- 총재산가액 = ⑥일반재산가액 + ⑦자동차가액 - ⑧부채(임차보증금 마련 용도의 부채만 인정)\n\n원가구 소득·재산평가액 산정 기준은 다음과 같습니다.\n\n○ 소득평가액이 「국민기초생활 보장법」 제2조제11호에 따른 기준 중위소득의 100% 이하\n- 소득평가액 = ①근로소득 + ②사업소득 + ③재산소득 + ④공적이전소득 - ⑤근로·사업소득공제\n\n○ 일반재산, 자동차 등의 재산에 관하여 총재산가액이 4.7억원 이하\n- 총재산가액 = ⑥일반재산가액 + ⑦자동차가액 - ⑧부채(주택구입·임차보증금 마련 용도의 부채만 인정)\n\n참고\n① (근로소득) 상시근로자소득\n② (사업소득) 기타사업소득\n③ (재산소득) 임대소득, 이자소득\n④ (공적이전소득) 국민연금급여, 사학퇴직연금급여, 공무원퇴직연금급여, 군인퇴직연금급여, 별정우체국연금, 산재보험급여(휴업급여, 장해급여, 유족급여, 상병보상금), 실업급여\n⑤ (근로소득공제) 근로·사업소득 30%\n⑥ (일반재산) 건축물(건물, 시설물, 기타), 주택, 토지(밭, 논, 대지, 임야, 기타), 임차보증금(전월세보증금, 상가보증금), 선박, 항공기, 회원권(골프, 콘도미니엄, 승마, 종합체육시설이용, 요트)\n⑦ (자동차) 자동차가액\n⑧ (부채) 다음에 따른 공적서류를 제출한 경우에만 인정\n- 대출금: 금융기관 대출금, 금융기관이 아닌 기관 대출금\n- 공공기관 대출금: 농지연금 등\n※ 주택구입, 임차보증금 마련 용도의 부채만 인정\n※ 취득한 주택의 등기사항 증명서 상 소유권 이전등기 접수일로부터 3개월 이내 대출한 자금의 경우 주택구입자금으로 인정","refUrlAddr1":"https://www.bokjiro.go.kr/ssis-tbu/ssis-tbu/twataa/wlfareInfo/moveTWAT52011M.do?wlfareInfoId=WLF00004661","refUrlAddr2":"https://www.youthcenter.go.kr/bbs03View/10003/10455","sprtSclCnt":"60000","sprtArvlSeqYn":"N","sprtTrgtMinAge":"19","sprtTrgtMaxAge":"34","sprtTrgtAgeLmtYn":"N","mrgSttsCd":"0055003","earnCndSeCd":"0043003","earnMinAmt":"0","earnMaxAmt":"0","earnEtcCn":"하단참고","addAplyQlfcCndCn":"19세~34세 독립거주 무주택 청년 중 청년가구 소득이 기준 중위소득 60% 이하이면서, 원가구 소득이 중위소득 100% 이하인 청년을 지원합니다.\n※ ①30세 이상, ②혼인(이혼), ③미혼부·모, ④30세 미만 미혼 청년의 소득이 중위소득 50% 이상으로 생계를 달리한다고 시·군·구청장이 인정하는 경우 등은 원가구 소득 미고려\n\n○ (청년가구) 청년 + 배우자 + 직계비속 + 동일 주소지에 거주하는 그 외 민법상 가족\n○ (원가구) 청년독립가구 + 1촌이내 직계혈족(부·모)","ptcpPrpTrgtCn":"○ 주택 소유자(분양권, 입주권 포함)\n○ 직계존속·형제·자매 등 2촌 이내 혈족(배우자의 2촌 이내 혈족 포함) 주택 임차\n○ 공공주택특별법에 따른 공공임대주택(공무원임대주택 포함) 거주\n○ 1실(방)에 다수가 거주하는 방식의 전대차인 경우 단, 1실에 다수가 거주하는 경우라도 임대인과 별도 임대차계약 체결 시 지원 가능\n○ 국토부 또는 지자체에서 시행하는 청년월세 지원사업 중복 수혜중인 자(수혜종료 후 신청 가능) 등\n○ 과거 ‘청년월세 한시 특별지원사업’에 선정되어 이미 24개월을 수혜받은 자 등","inqCnt":"48540","rgtrInstCd":"B551904","rgtrInstCdNm":"한국고용정보원","rgtrUpInstCd":"B000000","rgtrUpInstCdNm":"정부산하기관및위원회","rgtrHghrkInstCd":"B000000","rgtrHghrkInstCdNm":"정부산하기관및위원회","zipCd":"11110,11140,11170,11200,11215,11230,11260,11290,11305,11320,11350,11380,11410,11440,11470,11500,11530,11545,11560,11590,11620,11650,11680,11710,11740,12110,12130,12150,12170,12190,12210,12240,12270,12300,12330,12710,12720,12730,12740,12750,12760,12770,12780,12790,12800,12810,12820,12830,12840,12850,12860,12870,26110,26140,26170,26200,26230,26260,26290,26320,26350,26380,26410,26440,26470,26500,26530,26710,27110,27140,27170,27200,27230,27260,27290,27710,27720,28125,28177,28185,28200,28237,28245,28290,28710,28720,30110,30140,30170,30200,30230,31110,31140,31170,31200,31710,36110,41111,41113,41115,41117,41131,41133,41135,41150,41171,41173,41192,41194,41196,41210,41220,41250,41271,41273,41281,41285,41287,41290,41310,41360,41370,41390,41410,41430,41450,41461,41463,41465,41480,41500,41550,41570,41591,41593,41595,41597,41610,41630,41650,41670,41800,41820,41830,43111,43112,43113,43114,43130,43150,43720,43730,43740,43745,43750,43760,43770,43800,44131,44133,44150,44180,44200,44210,44230,44250,44270,44710,44760,44770,44790,44800,44810,44825,47111,47113,47130,47150,47170,47190,47210,47230,47250,47280,47290,47730,47750,47760,47770,47820,47830,47840,47850,47900,47920,47930,47940,48121,48123,48125,48127,48129,48170,48220,48240,48250,48270,48310,48330,48720,48730,48740,48820,48840,48850,48860,48870,48880,48890,50110,50130,51110,51130,51150,51170,51190,51210,51230,51720,51730,51750,51760,51770,51780,51790,51800,51810,51820,51830,52111,52113,52130,52140,52180,52190,52210,52710,52720,52730,52740,52750,52770,52790,52800","plcyMajorCd":"0011009","jobCd":"0013010","schoolCd":"0049010","aplyYmd":"20260330 ~ 20260529","frstRegDt":"2026-03-19 10:47:38","lastMdfcnDt":"2026-03-19 11:26:40","sbizCd":"0014010"}]}}}'::jsonb,
