insert into public.policy_raw (kind, external_id, title, url, payload, retrieved_at, retrieved_by) values (
  '온통청년API', '20260527005400113223', '전세보증금반환보증 보증료 지원', 'https://www.youthcenter.go.kr/go/ythip/getPlcy?rtnType=json&plcyNo=20260527005400113223',
  '{"api":"온통청년 청년정책 API — https://www.youthcenter.go.kr/go/ythip/getPlcy","query":{"plcyNo":"20260527005400113223","rtnType":"json","pageNum":1,"pageSize":5},"policyId":"jeonse-return-guarantee-fee-subsidy","fetchedAt":"2026-11-12T11:13:50.339Z","response":{"resultCode":200,"resultMessage":"성공적으로 데이터를 가지고 왔습니다.","result":{"youthPolicyList":[{"plcyNo":"20260527005400113223","bscPlanCycl":"2","bscPlanPlcyWayNo":"003","bscPlanFcsAsmtNo":"009","bscPlanAsmtNo":"031","pvsnInstGroupCd":"0054001","plcyPvsnMthdCd":"0042007","plcyAprvSttsCd":"0044002","plcyNm":"전세보증금반환보증 보증료 지원","plcyKywdNm":null,"plcyExplnCn":"전세사기, 역전세 등 임차인이 전세보증금을 돌려받지 못하는 전세 피해를 예방하고, 상대적으로 주거 취약계층인 청년 및 저소득층의 주거 안정을 도모","lclsfNm":null,"mclsfNm":null,"plcySprtCn":"○ 지원대상\n- 신청일 기준 유효한 전세보증금반환보증(HUG, HF, SGI)에 가입한 임차보증금 3억원 이하, 연소득 (청년) 5천만원, (청년외) 6천만원, (신혼부부) 7.5천만원 이하 무주택 임차인\n\n○ 지원금\n- 신청인이 기납부한 전세보증금반환보증 보증료에 대해 최대 40만원 한도 내 지원(''25.3.30 이전 가입건은 최대 30만원 지원)\nㆍ단, 청년외의 경우 신청인이 기납부한 보증료의 90%를 최대 40만원 한도 내 지원\n\n○ 신청시기\n- 연중 (지자체별 예산 소진시 조기 마감)","sprvsnInstCd":"1613000","sprvsnInstCdNm":"국토교통부","sprvsnInstPicNm":"","operInstCd":"1613000","operInstCdNm":"국토교통부","operInstPicNm":"","sprtSclLmtYn":"Y","aplyPrdSeCd":"0057002","bizPrdSeCd":"0056002","bizPrdBgngYmd":"        ","bizPrdEndYmd":"        ","bizPrdEtcCn":"상시","plcyAplyMthdCn":"○ 신청방법 : 시·군·구청 또는 주민센터에 방문 접수 혹은 온라인 접수\n※ 방문접수의 경우 구군별 상이하니 전화 후 방문 필요\n* 대구광역시는 온라인 접수 또는 시청 방문 신청\n\n○ 지급시기 및 지급방법\n- 지급일 : 접수 후 심사를 거쳐 30일 이내(기간 연장 필요한 경우 신청인 통지 후 15일 연장 가능) 지급\n- 지급방법 : 신청인 계좌에 직접 입금\n\n○ 신청 처리상태 안내\n- 알림수신에 동의하신 경우 SMS/국민비서를 통해 처리상태를 안내받으실 수 있습니다.\n※ 알림수신 동의 참고사항\n1. 정부24 → MyGOV → 나의 정보관리 → 알림 수신동의 → SMS/국민비서 (예)로 변경\n2. 국민비서 → 로그인 → 화면 좌측에 국민비서 알림 체크 → 화면 좌측에 수신받을 앱 선택 → 화면 우측에 알림서비스 선택 (정부 24 체크)","srngMthdCn":"○ 보증기관에서 보증가입 시 전세보증금반환보증 보증료 지원 사업을 위한 제3자 정보제공에 동의한 경우\n- 보증료 지원 신청서, 서약서\n\n○ 신청인 제출 서류\n- 보증료 지원 신청 및 서약서, 지급받을 계좌의 통장 사본\n- 전세보증금반환보증 보증서(보증기관 날인 필수), 보증료 납부 증빙서류*(납부액 기재, 보증기관 날인 필수)\n* HUG와 SGI의경우 보증서에 보증료가 기재되어 있으므로 별도 증빙서류 불필요\n- 임대차계약서, 부동산 등기사항 전부증명서\n- 주민등록등본(전체공개), 혼인관계증명서(일반증명서, 전부공개, 국내기관제출용)\n- 소득금액증빙자료(열람용은 법적 효력 없음)\n(근로소득) 아래 서류 중 택1\n· 최근년도 근로소득원천징수 영수증\n· 전년도 소득금액 증명원(7.1일 이전은 전전년도 소득금액증명원)\n· 소득확인증명서(ISA 가입용)\n· 갑근세원천징수확인서(홈택스에서 발급시 관공서 제출용, 회사 발급시 회사 직인 필요)\n· 급여명세표, 임금대장 등 최근 1년간의 급여액을 알 수 있는 자료\n(사업소득) 아래 서류 중 택1\n· 전년도 소득금액 증명원(7.1일 이전은 전전년도 소득금액증명원)\n· 소득확인증명서(ISA 가입용)\n· 종합소득세 과세표준확정신고 및 납부 계산서(세무사 확인분)\n· 사업소득원천징수영수증(연말정산용)\n(연금소득) 연금수급권자 확인서 등 기타 연금을 확인할 수 있는 지급기관의 증명서(단, 연금수령액이 표기되지 않는 경우 연금 수령통장)\n* 기존 소득심사방법과 동일하게 소득금액증명원 제출시 별도 서류 제출하지 않아도 무방하나, 그 외 소득확인증명서 등 재직기간 확인이 어려운 경우는 재직증명서, 건강보험자격득실확인서 등 재직기간을 확인할 수 있는 서류 추가 제출 필요\n** 소득이 발생하지 않아 소득금액증명이 발급되지 않는 경우에는 ''사실증명(신고사실없음)'' 제출\n*** 기혼자는 배우자의 소득증빙 서류도 필수 제출\n- 대리신청의 경우 위임장, 대리인 신분증, 본인-대리인 관계 증명 서류 제출\n\n※ 소득금액증명 상 연소득 확인:\n- (근로소득) 종합소득세 신고 현황 - 수입금액 / 연말정산 현황 - 지급받은 총액\n- (그 외 소득) 종합소득 신고 현황 - 소득금액 합계 / 연말정산 현황 - 소득금액 합계\n※ 모든 서류는 신청일 기준 3개월 이내에 발급한 서류로 제출","aplyUrlAddr":"https://www.gov.kr/portal/rcvfvrSvc/dtlEx/161300000103","sbmsnDcmntCn":"<민원인이 제출해야 하는 서류>\n○ 보증기관에서 보증가입 시 전세보증금반환보증 보증료 지원 사업을 위한 제3자 정보제공에 동의한 경우\n- 보증료 지원 신청서, 서약서\n\n○ 신청인 제출 서류\n- 보증료 지원 신청 및 서약서, 지급받을 계좌의 통장 사본\n- 전세보증금반환보증 보증서(보증기관 날인 필수), 보증료 납부 증빙서류*(납부액 기재, 보증기관 날인 필수)\n* HUG와 SGI의경우 보증서에 보증료가 기재되어 있으므로 별도 증빙서류 불필요\n- 임대차계약서, 부동산 등기사항 전부증명서\n- 주민등록등본(전체공개), 혼인관계증명서(일반증명서, 전부공개, 국내기관제출용)\n- 소득금액증빙자료(열람용은 법적 효력 없음)\n(근로소득) 아래 서류 중 택1\n· 최근년도 근로소득원천징수 영수증\n· 전년도 소득금액 증명원(7.1일 이전은 전전년도 소득금액증명원)\n· 소득확인증명서(ISA 가입용)\n· 갑근세원천징수확인서(홈택스에서 발급시 관공서 제출용, 회사 발급시 회사 직인 필요)\n· 급여명세표, 임금대장 등 최근 1년간의 급여액을 알 수 있는 자료\n(사업소득) 아래 서류 중 택1\n· 전년도 소득금액 증명원(7.1일 이전은 전전년도 소득금액증명원)\n· 소득확인증명서(ISA 가입용)\n· 종합소득세 과세표준확정신고 및 납부 계산서(세무사 확인분)\n· 사업소득원천징수영수증(연말정산용)\n(연금소득) 연금수급권자 확인서 등 기타 연금을 확인할 수 있는 지급기관의 증명서(단, 연금수령액이 표기되지 않는 경우 연금 수령통장)\n* 기존 소득심사방법과 동일하게 소득금액증명원 제출시 별도 서류 제출하지 않아도 무방하나, 그 외 소득확인증명서 등 재직기간 확인이 어려운 경우는 재직증명서, 건강보험자격득실확인서 등 재직기간을 확인할 수 있는 서류 추가 제출 필요\n** 소득이 발생하지 않아 소득금액증명이 발급되지 않는 경우에는 ''사실증명(신고사실없음)'' 제출\n*** 기혼자는 배우자의 소득증빙 서류도 필수 제출\n- 대리신청의 경우 위임장,